async function loadSlow(userId: string) {
  const user = await getUser(userId)
  const posts = await getPosts(user.id)
  const flags = await getFlags() // independent — wasted round trip
  return { user, posts, flags }
}

async function loadFast(userId: string) {
  const [user, flags] = await Promise.all([getUser(userId), getFlags()])
  const posts = await getPosts(user.id) // real dependency
  return { user, posts, flags }
}

// .then chain of the same idea:
getUser(id)
  .then((user) => Promise.all([user, getFlags(), getPosts(user.id)]))
  .catch((err) => {
    reportError(err)
    throw err
  })

